window.AUTH=window.AUTH||{};window.AUTH["04-1084"]={"d":"04-1084","id":"2005/04-1084","n":"Gonzales v. O Centro Espírita Beneficente União do Vegetal","src":["osg"],"briefs":[{"k":"petitioner","label":"Brief for the petitioners","date":"","url":"https://www.justice.gov/osg/media/227741/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/gonzales-v-o-centro-brief-merits","n":148}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep546/usrep546418/usrep546418.pdf","tr":true,"items":[{"t":"case","label":"Ashcroft v. ACLU","cite":"542 U.S. 656","y":2004,"id":"2003/03-218","sc":1,"op":6,"ar":1,"sum":"In an interesting 5-to-4 vote, with Justices Kennedy, Stevens, Souter, Thomas and Ginsburg on one side and Chief Justice Rehnquist and Justices Scalia, Breyer and O'Connor on the other, the Court found that Congress had not yet met its burden to show that the COPA requirements were more effective than other methods of preventing minors.","sumSrc":"Oyez","by":{"0":"12, 13"}},{"t":"case","label":"Atari Games Corp. v. Nintendo of America, Inc.","cite":"975 F.2d 832","y":1992,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/975/832/","by":{"0":"12"}},{"t":"case","label":"Board of Educ. v. Mergens","cite":"496 U.S. 226","y":1990,"id":"1989/88-1597","sc":1,"sum":"The Court held that the Equal Access Act stopped Westside High School from prohibiting the formation of religious-based non-curricular student clubs.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Board of Educ. of Indep. Sch. Dist. No. 92 v. Earls","cite":"536 U.S. 822","y":2002,"id":"2001/01-332","sc":1,"sum":"The Court held that an Oklahoma public school's random drug testing of its students was constitutional, since the policy reasonably served the district's important interest in detecting and preventing drug use in its student body.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Board of Educ. of Kiryas Joel v. Grumet","cite":"512 U.S. 687","y":1994,"id":"1993/93-517","sc":1,"sum":"In a 6-to-3 decision, the Court held that the statute's purpose was to exclude all but those who lived in and practiced the village enclave's extreme form of Judaism.","sumSrc":"Oyez","by":{"0":"20, 21, 24"}},{"t":"case","label":"Bob Jones Univ. v. United States","cite":"461 U.S. 574","y":1983,"id":"1982/81-3","sc":1,"sum":"The Court found that the IRS was correct in its decision to revoke the tax-exempt status of Bob Jones University and the Goldsboro Christian School. These institutions did not meet the requirement by providing \"beneficial and stabilizing influences in community life\" to be supported by taxpayers with a special tax status. The schools could not meet this requirement due to their discriminatory policies.","sumSrc":"Oyez","by":{"0":"20, 28"}},{"t":"case","label":"Braunfeld v. Brown","cite":"366 U.S. 599","y":1961,"id":"1960/67","sc":1,"op":3,"ar":1,"sum":"In a 6-to-3 decision, the Court held that the Pennsylvania blue law did not violate the Free Exercise Clause. The freedom to hold religious beliefs and opinions is absolute; however, the freedom to act (even in accordance with religious convictions) is not totally free from government restrictions. The Court found that the Sunday Closing Law had a secular basis and did not make any religious practices unlawful.","sumSrc":"Oyez","by":{"0":"16, 20"}},{"t":"case","label":"Brolan v. United States","cite":"236 U.S. 216","y":1915,"id":"scdb/1914-209","sc":1,"sum":"In a case from the District Court, if the power to review attaches because of a constitutional question, that authority gives rise to the duty of determining all the questions involved, including those that otherwise are within the exclusive jurisdiction of the District Court, but if the constitutional question asserted as the basis for jurisdiction of this court is frivolous, this court has no power to review it or …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Buttfield v. Stranahan","cite":"192 U.S. 470","y":1904,"id":"scdb/1903-187","sc":1,"sum":"Every intendment is in favor of the validity of a statute and it must be presumed to' be constitutional unless its repugnancy to the Constitution clearly appears.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Cannon v. University of Chicago","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"sum":"Petitioner may maintain her lawsuit, despite the absence of any express authorization for it in Title IX.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Chan v. Korean Air Lines, Ltd.","cite":"490 U.S. 122","y":1989,"id":"1988/87-1055","sc":1,"sum":"International air carriers do not lose the benefit of the Warsaw Convention's damages limitation if they fail to provide notice of that limitation in passenger tickets. The Montreal Agreement concededly does not impose such a sanction, and the Convention's plain language also does not direct that result. Interpreting the second sentence of Article 3(2) of the Convention-which subjects a carrier to unlimited …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Chicago & S. Air Lines, Inc. v. Waterman S.S. Corp.","cite":"333 U.S. 103","y":1948,"id":"scdb/1947-037","sc":1,"by":{"0":"49"}},{"t":"case","label":"City of Indianapolis v. Edmond","cite":"531 U.S. 32","y":2000,"id":"2000/99-1030","sc":1,"sum":"The Court held that because the checkpoint program's primary purpose was indistinguishable from the general interest in crime control, the checkpoints violated the Fourth Amendment. \"We cannot sanction stops justified only by the generalized and ever-present possibility that interrogation and inspection may reveal that any given motorist has committed some crime,\" wrote Justice O'Connor.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Coastal Fuels of Puerto Rico, Inc. v. Caribbean Petroleum Corp.","cite":"990 F.2d 25","y":1993,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/990/25/","by":{"0":"12"}},{"t":"case","label":"Collins v. Smith","cite":"1985 WL 12924","y":1985,"court":"6th Cir. Feb. 14","by":{"0":"25"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"125 S. Ct. 2113","y":2005,"id":"2004/03-9877","sc":1,"op":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"0":"10, 19, 20"}},{"t":"case","label":"Dickinson v. Zurko","cite":"527 U.S. 150","y":1999,"id":"1998/98-377","sc":1,"sum":"The Court held that the Court of Appeals for the Federal Circuit must use the framework set forth in the Administrative Procedure Act when reviewing PTO findings of fact.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Doran v. Salem Inn, Inc.","cite":"422 U.S. 922","y":1975,"id":"1974/74-337","sc":1,"op":1,"sum":"Three corporations (M & L, Salem, and Tim-Rob), on August 9, 1973, filed a complaint in District Court, seeking a temporary restraining order, preliminary injunction, and declaratory relief, against Doran, a law enforcement official, claiming that a North Hempstead, N. Y., ordinance proscribing topless dancing, which the corporations had provided as entertainment in their bars, violated their First and Fourteenth …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10, 11, 12"}},{"t":"case","label":"DSC Communications Corp. v. DGI Techs., Inc.","cite":"81 F.3d 597","y":1996,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/81/597/","by":{"0":"12"}},{"t":"case","label":"El Al Israel Airlines, Ltd. v. Tsui Yuan Tseng","cite":"525 U.S. 155","y":1999,"id":"1998/97-475","sc":1,"sum":"Announced by Justice Ruth Bader Ginsburg, the Court ruled that the Warsaw Convention precludes a passenger from maintaining an action for personal injury damages under local law when her claim does not satisfy the conditions for liability under the Convention.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Employment Div., Dep’t of Human Res. v. Smith","cite":"494 U.S. 872","y":1990,"id":"1989/88-1213","sc":1,"op":4,"sum":"The Court held that the First Amendment does not protect individuals engaging in illegal acts as part of a religious ceremony.","sumSrc":"Oyez","by":{"0":"10, 13, 17, 18, 25, 28"}},{"t":"case","label":"F. Hoffman-La Roche Ltd. v. Empagran, S.A.","cite":"124 S. Ct. 2359","y":2004,"id":"2003/03-724","sc":1,"sum":"The Court unanimously ruled that Congress' intent in passing the FTAIA was to prevent American courts from interfering in foreign commerce. Congress made an exception for foreign commerce that affected domestic commerce, but the exception should not be read as a general prohibition against price-fixing in all parts of the world.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Gaskin v. State","cite":"490 S.W.2d 521","y":1973,"court":"Tenn.","url":"https://www.courtlistener.com/c/S.W.2d/490/521/","by":{"0":"25"}},{"t":"case","label":"Golden Eagle v. Johnson","cite":"493 F.2d 1179","y":1974,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/493/1179/","by":{"0":"25"}},{"t":"case","label":"Goldman v. Weinberger","cite":"475 U.S. 503","y":1986,"id":"1985/84-1097","sc":1,"sum":"The Court held that the Air Force regulation did not violate the Constitution.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Gonzales v. Raich","cite":"125 S. Ct. 2195","y":2005,"id":"2004/03-1454","sc":1,"sum":"The Court ruled that the commerce clause of the Controlled Substances Act gives Congress authority to prohibit the local cultivation and use of marijuana, despite state law to the contrary.","sumSrc":"Oyez","by":{"0":"13, 14, 18, 19, 39, 43"}},{"t":"case","label":"Harisiades v. Shaughnessy","cite":"342 U.S. 580","y":1952,"id":"scdb/1951-056","sc":1,"by":{"0":"44"}},{"t":"case","label":"Harmelin v. Michigan","cite":"501 U.S. 957","y":1991,"id":"1990/89-7272","sc":1,"sum":"The Court, in a 5-to-4 decision, held that since the Eighth Amendment does not contain a proportionality guarantee, the determination of whether a punishment is \"cruel and unusual\" is not made with reference to the particular offense. Moreover, the Cruel and Unusual Punishment Clause protects against unusual methods of punishment, not necessarily cruel ones.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Heffron v. International Soc’y for Krishna Consciousness, Inc.","cite":"452 U.S. 640","y":1981,"id":"1980/80-795","sc":1,"sum":"Using the \"valid time, manner, and place\" criteria which the Court employs to assess government restrictions of First Amendment activities, the Court held that Rule 6.05 did not violate the Constitution.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Hernandez v. Commissioner","cite":"490 U.S. 680","y":1989,"id":"1988/87-963","sc":1,"op":2,"ar":1,"sum":"Payments made to the Church's branch churches for auditing and training services are not deductible charitable contributions under § 170.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 20, 28, 48"}},{"t":"case","label":"Herdon v. United States","cite":"405 F.2d 882","y":1968,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/405/882/","by":{"0":"25"}},{"t":"case","label":"Indian Inmates of Neb. Penitentiary v. Grammer","cite":"649 F. Supp. 1375","y":1986,"court":"D. Neb.","url":"https://www.courtlistener.com/c/F.%20Supp./649/1375/","op":1,"ar":8,"by":{"0":"25"}},{"t":"case","label":"INS v. Aquirre-Aguirre","cite":"526 U.S. 415","y":1999,"id":"1998/97-1754","sc":1,"sum":"The Court noted that withholding of deportation is mandatory if an alien establishes that it is more likely than not that he or she will suffer political persecution if deported.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"INS v. Elias-Zacarias","cite":"502 U.S. 478","y":1992,"id":"1991/90-1342","sc":1,"sum":"A guerrilla organization's attempt to coerce a person into performing military service does not necessarily constitute \"persecution on account of... political opinion\" under § 101(a)(42) of the Immigration and Nationality Act, 8 U. S. C. §1101(a)(42). Even one who supports the political aims of a guerrilla movement might resist military combat and thus become the object of such coercion. Moreover, persecution on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Jacobson v. Massachusetts","cite":"197 U.S. 11","y":1905,"id":"1900-1940/197us11","sc":1,"sum":"The Court held that the law was a legitimate exercise of the state's police power to protect the public health and safety of its citizens. Local boards of health determined when mandatory vaccinations were needed, thus making the requirement neither unreasonable nor arbitrarily imposed.","sumSrc":"Oyez","by":{"0":"29, 30, 31"}},{"t":"case","label":"Johnson v. California","cite":"125 S. Ct. 1141","y":2005,"url":"https://www.courtlistener.com/c/S.%20Ct./125/1141/","sc":1,"by":{"0":"10"}},{"t":"case","label":"Jones v. United States","cite":"463 U.S. 354","y":1983,"id":"1982/81-5195","sc":1,"sum":"When a criminal defendant establishes by a preponderance of the evidence that he is not guilty of a crime by reason of insanity, the Constitution permits the Government, on the basis of the insanity judgment, to confine him to a mental institution until such time as he has regained his sanity or is no longer a danger to himself or society.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Kennedy v. Bureau of Narcotics & Dangerous Drugs","cite":"459 F.2d 415","y":1972,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/459/415/","by":{"0":"25"}},{"t":"case","label":"Kolovrat v. Oregon","cite":"366 U.S. 187","y":1961,"id":"1960/102","sc":1,"sum":"An 1881 treaty between the United States and Serbia, which is now a part of Yugoslavia, entitles residents and citizens of Yugoslavia to inherit personal property located in Oregon on the same basis as American next of kin, and these rights have not been taken away or impaired by the monetary policies of Yugoslavia exercised in accordance with later agreements between that country and the United States.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Kontes Glass Co. v. Lab Glass, Inc.","cite":"373 F.2d 319","y":1967,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/373/319/","by":{"0":"12"}},{"t":"case","label":"Lambert v. Yellowley","cite":"272 U.S. 581","y":1926,"id":"scdb/1926-021","sc":1,"sum":"1. The provision of the National Prohibition Act that \"Not more than a pint of spirituous liquor to be taken internally shall be Argument for Appellant. prescribed for use by the same person within any period of ten days and no prescription shall be filled more than once,\" is \"appropriate legislation,\" within the meaning of the Eighteenth Amendment for enforcing its prohibition of the manufacture, sale, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Larkin v. Grendel’s Den, Inc.","cite":"459 U.S. 116","y":1982,"id":"1982/81-878","sc":1,"sum":"Section 16C violates the Establishment Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Leary v. United States","cite":"383 F.2d 851","y":1967,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/383/851/","by":{"0":"25"}},{"t":"case","label":"Lexmark Int’l, Inc. v. Static Control Components, Inc.","cite":"387 F.3d 522","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/387/522/","by":{"0":"12"}},{"t":"case","label":"Lewellyn v. State","cite":"489 P.2d 511","y":1971,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P.2d/489/511/","by":{"0":"25"}},{"t":"case","label":"Marshall v. United States","cite":"414 U.S. 417","y":1974,"id":"1973/72-5881","sc":1,"sum":"Title II of NARA does not deny due process or equal protection by excluding from rehabilitative commitment, in lieu of penal incarceration, addicts with two or more prior felony convictions, since Congress could rationally assume that an addict with a multiple-felony record is likely to benefit less from rehabilitative treatment, present a possible impediment to the successful treatment of others, and be a greater …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Mazurek v. Armstrong","cite":"520 U.S. 968","y":1997,"id":"1996/96-1104","sc":1,"op":1,"sum":"The Court held that the Court of Appeals' finding that the practitioners had shown a fair chance of success on the merits was erroneous. The Court noted that its precedents repeatedly stated that the performance of abortions could be restricted to physicians, where there was no evidence of an unlawful motive on the part of the state legislature.","sumSrc":"Oyez","by":{"0":"10, 12"}},{"t":"case","label":"McConnell v. FEC","cite":"540 U.S. 93","y":2003,"id":"2003/02-1674","sc":1,"sum":"The Court found that regulations in the Campaign Finance Reform Act of 2002 did not violate the First Amendment.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"op":1,"ar":1,"sum":"In addition, the Court held that Section 472 did not constitute discrimination in violation of the Fifth Amendment. Again, Justice Blackmun cited the history of \"special treatment\" granted to Indians.","sumSrc":"Oyez","by":{"0":"27, 28"}},{"t":"case","label":"Mova Pharm. Corp. v. Shalala","cite":"140 F.3d 1060","y":1998,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/140/1060/","by":{"0":"12"}},{"t":"case","label":"Murray v. The Charming Betsy","cite":"6 U.S. 64","y":1804,"id":"scdb/1804-007","sc":1,"op":1,"sum":"Rejecting exemption from Sunday closing law, in part because of the need for uniformity and the difficulties of exempting all persons “who, because of religious conviction, observe a day of rest other than Sunday”.","sumSrc":"brief:0","by":{"0":"41"}},{"t":"case","label":"National Treasury Employees Union v. Van Raab","cite":"489 U.S. 656","y":1989,"id":"1988/86-1879","sc":1,"sum":"The Court held that the \"substantial interests\" of the government in stifling the drug trade justified \"departure from the ordinary warrant and probable cause requirements\" associated with searches.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Native American Church v. Navajo Tribal Council","cite":"272 F.2d 131","y":1959,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/272/131/","op":4,"ar":12,"by":{"0":"25"}},{"t":"case","label":"Oliver v. Udall","cite":"306 F.2d 819","y":1962,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/306/819/","by":{"0":"24"}},{"t":"case","label":"Olsen v. DEA","cite":"878 F.2d 1458","y":1989,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/878/1458/","by":{"0":"24, 25"}},{"t":"case","label":"Olsen v. Iowa","cite":"808 F.2d 652","y":1986,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/808/652/","by":{"0":"25"}},{"t":"case","label":"People v. Collins","cite":"78 Cal. Rptr. 151","y":1969,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.%20Rptr./78/151/","by":{"0":"25"}},{"t":"case","label":"People v. Crawford","cite":"328 N.Y.S.2d 747","y":1972,"court":"Dist. Ct.","url":"https://www.courtlistener.com/c/N.Y.S.2d/328/747/","by":{"0":"25"}},{"t":"case","label":"People v. Evans","cite":"710 P.2d 1167","y":1985,"court":"Colo. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/710/1167/","by":{"0":"25"}},{"t":"case","label":"People v. Mitchell","cite":"52 Cal. Rptr. 884","y":1996,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.%20Rptr./52/884/","by":{"0":"26"}},{"t":"case","label":"People v. Mullins","cite":"123 Cal. Rptr. 201","y":1975,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.%20Rptr./123/201/","by":{"0":"25"}},{"t":"case","label":"People v. Werber","cite":"97 Cal. Rptr. 150","y":1971,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.%20Rptr./97/150/","by":{"0":"25"}},{"t":"case","label":"People v. Wright","cite":"80 Cal. Rptr. 335","y":1969,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.%20Rptr./80/335/","by":{"0":"26"}},{"t":"case","label":"Peyote Way Church of God, Inc. v. Thornburgh","cite":"922 F.2d 1210","y":1991,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/922/1210/","ar":1,"by":{"0":"25, 27"}},{"t":"case","label":"Prince v. Massachusetts","cite":"321 U.S. 158","y":1944,"id":"scdb/1943-096","sc":1,"sum":"1. A state statute provides that no minor (boy under 12 or girl under 18) shall sell, or offer for sale, upon the streets or in other public places, any newspapers, magazines, periodicals, or other articles of merchandise. The statute makes it unlawful for any person to furnish to a minor any article which he knows the minor intends to sell in violation of the law; and for any parent or guardian to permit a minor to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Quackenbush v. Allstate Ins. Co.","cite":"517 U.S. 706","y":1996,"id":"1995/95-244","sc":1,"sum":"The Court held that an abstention-based remand order is appealable because the \"remand order here falls within that narrow class of collateral orders that are immediately appealable.\" Further, the Court held that the \"federal courts have the power to dismiss or remand cases based on abstention principles only where the relief sought is equitable or otherwise discretionary,\" and because \"this was a damages action, the District Court's remand order was an unwarranted application of the Burford doctrine.\" Justices Antonin Scalia and Anthony M. Kennedy wrote concurring opinions.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"Randall v. Wyrick","cite":"441 F. Supp. 312","y":1977,"court":"D. Mo.","url":"https://www.courtlistener.com/c/F.%20Supp./441/312/","by":{"0":"24"}},{"t":"case","label":"Ratzlaf v. United States","cite":"510 U.S. 135","y":1994,"id":"1993/92-1196","sc":1,"sum":"To give effect to § 5322(a)'s \"willfulness\" requirement, the Government must prove that the defendant acted with knowledge that the structuring he or she undertook was unlawful, not simply that the defendant's purpose was to circumvent a bank's reporting obligation. Section 5324 itself forbids structuring with a \"purpose of evading the [§ 5313(a)] reporting requirements,\" and the lower courts erred in treating the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Regan v. Wald","cite":"468 U.S. 222","y":1984,"id":"1983/83-436","sc":1,"sum":"Treasury Department Regulation 201(b), first promulgated in 1963 as part of the Cuban Assets Control Regulations, prohibits any transaction involving property in which Cuba, or any national thereof, has \"any interest of any nature whatsoever, direct or indirect.\" Regulation 560, which was added to the Regulations in 1977, embodied a general license permitting, for the most part, travel-related economic transactions …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Reina v. United States","cite":"364 U.S. 507","y":1960,"id":"1960/29","sc":1,"sum":"The conviction is sustained. '","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Reynolds v. United States","cite":"98 U.S. 145","y":1878,"id":"1850-1900/98us145","sc":1,"ar":1,"sum":"The Court held that bigamy was not a protected religious act under the First Amendment.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Rheuark v. State","cite":"601 So.2d 135","y":1992,"court":"Ala. Ct. Crim. App.","url":"https://www.courtlistener.com/c/So.2d/601/135/","by":{"0":"25"}},{"t":"case","label":"Rupert v. City of Portland","cite":"605 A.2d 63","y":1992,"court":"Me.","url":"https://www.courtlistener.com/c/A.2d/605/63/","by":{"0":"24"}},{"t":"case","label":"Sherbert v. Verner","cite":"374 U.S. 398","y":1963,"id":"1962/526","sc":1,"op":5,"ar":1,"sum":"The Court found that the denial of unemployment compensation because of religious practices violated the First and Fourteenth Amendments.","sumSrc":"Oyez","by":{"0":"16, 21"}},{"t":"case","label":"Spector v. Norwegian Cruise Line Ltd.","cite":"125 S. Ct. 2169","y":2005,"id":"2004/03-1388","sc":1,"sum":"The Court held 6-3 that Title III applied to foreign-flag cruise ships in U.S. waters. Justice Kennedy delivered the Court's controlling opinion, which held that Title III did not apply to foreign ships' internal affairs, because there was no \"clear congressional statement\" showing an intent to do so. A clear statement was necessary before a general law could interfere with a foreign-vessel's internal affairs.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"State v. Blake","cite":"695 P.2d 336","y":1985,"court":"Haw. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/695/336/","by":{"0":"25"}},{"t":"case","label":"State v. Brashear","cite":"593 P.2d 63","y":1979,"court":"N.M. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/593/63/","by":{"0":"25"}},{"t":"case","label":"State v. Bullard","cite":"148 S.E.2d 565","y":1966,"court":"N.C.","url":"https://www.courtlistener.com/c/S.E.2d/148/565/","by":{"0":"25"}},{"t":"case","label":"State v. Flesher","cite":"585 N.E.2d 901","y":1990,"court":"Ohio Ct. App.","url":"https://www.courtlistener.com/c/N.E.2d/585/901/","by":{"0":"25"}},{"t":"case","label":"State v. Peck","cite":"422 N.W.2d 160","y":1988,"court":"Wis. Ct. App.","url":"https://www.courtlistener.com/c/N.W.2d/422/160/","by":{"0":"25"}},{"t":"case","label":"State v. Rocheleau","cite":"451 A.2d 1144","y":1982,"court":"Vt.","url":"https://www.courtlistener.com/c/A.2d/451/1144/","by":{"0":"25"}},{"t":"case","label":"State v. Soto","cite":"537 P.2d 142","y":1975,"court":"Or. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/537/142/","by":{"0":"25"}},{"t":"case","label":"State v. Venet","cite":"797 P.2d 1055","y":1990,"court":"Or. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/797/1055/","by":{"0":"25"}},{"t":"case","label":"Suntrust Bank v. Houghton Mifflin Co.","cite":"268 F.3d 1257","y":2001,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/268/1257/","by":{"0":"12"}},{"t":"case","label":"Town v. State ex rel. Reno","cite":"377 So.2d 648","y":1979,"court":"Fla.","url":"https://www.courtlistener.com/c/So.2d/377/648/","by":{"0":"25"}},{"t":"case","label":"Turner Broad. Sys., Inc. v. FCC","cite":"512 U.S. 622","y":1994,"id":"1993/93-44","sc":1,"sum":"The Court held that the must-carry provisions were content neutral, thus not a violation of the First Amendment. The rules were not determined by the programming content, but by broadcast method. The rules promote fair competition in television programming.","sumSrc":"Oyez","by":{"0":"29, 35"}},{"t":"case","label":"United States v. Alvarez-Machain","cite":"504 U.S. 655","y":1992,"id":"1991/91-712","sc":1,"sum":"The fact of respondent's forcible abduction does not prohibit his trial in a United States court for violations of this country's criminal laws.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"United States v. Balsys","cite":"524 U.S. 666","y":1998,"id":"1997/97-873","sc":1,"sum":"In a 7-to-2 decision, the Court held that although resident aliens are entitled to the same Fifth Amendment protections as citizen \"persons\" the risk of their deportation is not sufficient to sustain a self-incrimination privilege intended to apply only to the United States government.","sumSrc":"Oyez","by":{"0":"50"}},{"t":"case","label":"United States v. Boyll","cite":"774 F. Supp. 1333","y":1991,"court":"D.N.M.","url":"https://www.courtlistener.com/c/F.%20Supp./774/1333/","by":{"0":"26"}},{"t":"case","label":"United States v. Carlson","cite":"1992 WL 64772","y":1992,"court":"9th Cir. Apr. 2","by":{"0":"25"}},{"t":"case","label":"United States v. Dion","cite":"476 U.S. 734","y":1986,"id":"1985/85-246","sc":1,"sum":"The Court of Appeals erred in recognizing respondent's treaty defense to the prosecutions.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"United States v. Flores-Montano","cite":"541 U.S. 149","y":2004,"id":"2003/02-1794","sc":1,"sum":"The Court held that the government had authority to inspect a vehicle's fuel tank at the border without suspicion.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"United States v. Green","cite":"548 F.2d 1261","y":1977,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/548/1261/","by":{"0":"15"}},{"t":"case","label":"United States v. Greene","cite":"892 F.2d 453","y":1989,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/892/453/","by":{"0":"25"}},{"t":"case","label":"United States v. Hudson","cite":"431 F.2d 468","y":1970,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/431/468/","by":{"0":"25"}},{"t":"case","label":"United States v. Israel","cite":"317 F.3d 768","y":2003,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/317/768/","by":{"0":"20"}},{"t":"case","label":"United States v. Kuch","cite":"288 F. Supp. 439","y":1968,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./288/439/","by":{"0":"25"}},{"t":"case","label":"United States v. Lee","cite":"455 U.S. 252","y":1982,"id":"1981/80-767","sc":1,"op":1,"sum":"The Supreme Court held that the §1402(g) exemption only applied to self-employed individuals, not employers and employees like those involved in this case. The Court held that the tax was not unconstitutional as applied. By becoming an employer, Lee entered into commercial activity and accepted certain limits on the exercise of his beliefs.","sumSrc":"Oyez","by":{"0":"16, 20, 22, 28, 48"}},{"t":"case","label":"United States v. Mendenhall","cite":"446 U.S. 544","y":1980,"id":"1979/78-1821","sc":1,"sum":"The judgment is reversed, and the case is remanded. Pp. 550-560; 560-566. 596 F. 2d 706, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"United States v. Merkt","cite":"794 F.2d 950","y":1986,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/794/950/","by":{"0":"25"}},{"t":"case","label":"United States v. Middleton","cite":"690 F.2d 820","y":1982,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/690/820/","by":{"0":"25"}},{"t":"case","label":"United States v. Moore","cite":"423 U.S. 122","y":1975,"id":"1975/74-759","sc":1,"sum":"Registered physicians can be prosecuted under § 841 when, as here, their activities fall outside the usual course of professional practice.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"United States v. Oakland Cannabis Buyers Coop.","cite":"532 U.S. 483","y":2001,"id":"2000/00-151","sc":1,"ar":1,"sum":"The Court held that there is no medical necessity exception to the Controlled Substances Act's prohibitions on manufacturing and distributing marijuana. \"The statute reflects a determination that marijuana has no medical benefits worthy of an exception, \" wrote Justice Thomas, therefore, \"medical necessity is not a defense to manufacturing and distributing marijuana.\" Justice John Paul Stevens' concurring opinion, which was joined by Justices David H. Souter and Ruth Bader Ginsburg, argued that \"[b]ecause necessity was raised in this case as a defense to distribution, the Court need not venture an opinion on whether the defense is available to anyone other than distributors.\" Justice Stephen G. Breyer took no part in the consideration or decision of the case.","sumSrc":"Oyez","by":{"0":"18, 22"}},{"t":"case","label":"United States v. Rush","cite":"738 F.2d 497","y":1984,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/738/497/","by":{"0":"25"}},{"t":"case","label":"United States v. Rutherford","cite":"442 U.S. 544","y":1979,"id":"1978/78-605","sc":1,"sum":"The Act makes no express exception for drugs used by the terminally ill and no implied exemption is necessary to attain congressional objectives or to avert an unreasonable reading of the terms \"safe\" and \"effective\" in § 201 (p) (1). Pp. 551-559. UNITED STATES v. RUTHERFORD (a) Nothing in the legislative history suggests that Congress intended protection only for persons suffering from curable diseases. Moreover, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"United States v. Simon","cite":"842 F.2d 552","y":1988,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/842/552/","by":{"0":"25"}},{"t":"case","label":"United States v. Spears","cite":"443 F.2d 895","y":1971,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/443/895/","by":{"0":"25"}},{"t":"case","label":"United States v. Warner","cite":"595 F. Supp. 595","y":1984,"court":"D.N.D.","url":"https://www.courtlistener.com/c/F.%20Supp./595/595/","by":{"0":"25"}},{"t":"case","label":"University of Texas v. Camenisch","cite":"451 U.S. 390","y":1981,"id":"1980/80-317","sc":1,"sum":"The question whether a preliminary injunction should have been issued is moot because the terms of the injunction have been fully and irrevocably carried out, but, as the Court of Appeals correctly noted, the question whether the University must pay for the interpreter remains for trial on the merits.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11"}},{"t":"case","label":"Vimar Seguros Y Reaseguros, S.A. v. M/V Sky Reefer","cite":"515 U.S. 528","y":1995,"id":"1994/94-623","sc":1,"sum":"COGSA does not nullify foreign arbitration clauses contained in maritime bills of lading.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41, 45"}},{"t":"case","label":"Wahid v. State","cite":"716 P.2d 678","y":1986,"url":"https://www.courtlistener.com/c/P.2d/716/678/","by":{"0":"25"}},{"t":"case","label":"Weinberger v. Romero-Barcelo","cite":"456 U.S. 305","y":1982,"id":"1981/80-1990","sc":1,"sum":"Held that the district court was not obligated to enjoin the Navy from operating on and around Vieques island. He emphasized the traditional flexibility of equitable remedies and courts’ responsibility to balance plaintiffs’ need for an injunction with the public utility of the enjoined action.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"Weinberger v. Rossi","cite":"456 U.S. 25","y":1982,"id":"1981/80-1924","sc":1,"sum":"The word \"treaty\" as used in § 106 includes executive agreements, such as the one involved here, and is not limited to those international agreements concluded by the President with the advice and consent of the Senate pursuant to Art. II, § 2, cl. 2, of the Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Whyte v. United States","cite":"471 A.2d 1018","y":1984,"court":"D.C. Ct. App.","url":"https://www.courtlistener.com/c/A.2d/471/1018/","by":{"0":"25"}},{"t":"case","label":"Widmar v. Vincent","cite":"454 U.S. 263","y":1981,"id":"1981/80-689","sc":1,"sum":"Jr., the Court held that the university’s policy violated Cornerstone members’ First Amendment rights. He reasoned that when the university opened its facilities to student meetings, it created a public forum for those student groups; given no other justification, the university excluded Cornerstone based on the content of its members’ speech.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Wisconsin Right to Life, Inc. v. FEC","cite":"125 S. Ct. 2","y":2004,"url":"https://www.courtlistener.com/c/S.%20Ct./125/2/","sc":1,"by":{"0":"10"}},{"t":"case","label":"Wisconsin v. Yoder","cite":"406 U.S. 205","y":1972,"id":"1971/70-110","sc":1,"op":2,"sum":"The Court held that the First Amendment prohibited the state of Wisconsin to require Amish children to attend public school beyond the eighth grade.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"usc","label":"42 U.S.C. § 1996a","url":"https://www.law.cornell.edu/uscode/text/42/1996a","subs":["(a)(1)","(a)(5)","(b)(1)","(b)(6)","(c)(1)","(c)(2)","(c)(3)"],"stext":{"head":"§1996a. Traditional Indian religious use of peyote","paras":[[0,"(a) Congressional findings and declarations"],[0,"The Congress finds and declares that—"],[1,"(1) for many Indian people, the traditional ceremonial use of the peyote cactus as a religious sacrament has for centuries been integral to a way of life, and significant in perpetuating Indian tribes and cultures;"],[1,"(2) since 1965, this ceremonial use of peyote by Indians has been protected by Federal regulation;"],[1,"(3) while at least 28 States have enacted laws which are similar to, or are in conformance with, the Federal regulation which protects the ceremonial use of peyote by Indian religious practitioners, 22 States have not done so, and this lack of uniformity has created hardship for Indian people who participate in such religious ceremonies;"],[1,"(4) the Supreme Court of the United States, in the case of Employment Division v. Smith, 494 U.S. 872 (1990), held that the First Amendment does not protect Indian practitioners who use peyote in Indian religious ceremonies, and also raised uncertainty whether this religious practice would be protected under the compelling State interest standard; and"],[1,"(5) the lack of adequate and clear legal protection for the religious use of peyote by Indians may serve to stigmatize and marginalize Indian tribes and cultures, and increase the risk that they will be exposed to discriminatory treatment."],[0,"(b) Use, possession, or transportation of peyote"],[0,"(1) Notwithstanding any other provision of law, the use, possession, or transportation of peyote by an Indian for bona fide traditional ceremonial purposes in connection with the practice of a traditional Indian religion is lawful, and shall not be prohibited by the United States or any State. No Indian shall be penalized or discriminated against on the basis of such use, possession or transportation, including, but not limited to, denial of otherwise applicable benefits under public assistance programs."],[0,"(2) This section does not prohibit such reasonable regulation and registration by the Drug Enforcement Administration of those persons who cultivate, harvest, or distribute peyote as may be consistent with the purposes of this section and section 1996 of this title."],[0,"(3) This section does not prohibit application of the provisions of section 481.111(a) of Vernon's Texas Health and Safety Code Annotated, in effect on October 6, 1994, insofar as those provisions pertain to the cultivation, harvest, and distribution of peyote."],[0,"(4) Nothing in this section shall prohibit any Federal department or agency, in carrying out its statutory responsibilities and functions, from promulgating regulations establishing reasonable limitations on the use or ingestion of peyote prior to or during the performance of duties by sworn law enforcement officers or personnel directly involved in public transportation or any other safety-sensitive positions where the performance of such duties may be adversely affected by such use or ingestion. Such regulations shall be adopted only after consultation with representatives of traditional Indian religions for which the sacramental use of peyote is integral to their practice. Any regulation promulgated pursuant to this section shall be subject to the balancing test set forth in section 3 of the Religious Freedom Restoration Act (Public Law 103–141; 42 U.S.C. 2000bb–1)."],[0,"(5) This section shall not be construed as requiring prison authorities to permit, nor shall it be construed to prohibit prison authorities from permitting, access to peyote by Indians while incarcerated within Federal or State prison facilities."],[0,"(6) Subject to the provisions of the Religious Freedom Restoration Act (Public Law 103–141; 42 U.S.C. 2000bb–1) [42 U.S.C. 2000bb et seq.], this section shall not be construed to prohibit States from enacting or enforcing reasonable traffic safety laws or regulations."],[0,"(7) Subject to the provisions of the Religious Freedom Restoration Act (Public Law 103–141; 42 U.S.C. 2000bb–1), this section does not prohibit the Secretary of Defense from promulgating regulations establishing reasonable limitations on the use, possession, transportation, or distribution of peyote to promote military readiness, safety, or compliance with international law or laws of other countries. Such regulations shall be adopted only after consultation with representatives of traditional Indian religions for which the sacramental use of peyote is integral to their practice."],[0,"(c) Definitions"],[0,"For purposes of this section—"],[1,"(1) the term \"Indian\" means a member of an Indian tribe;"],[1,"(2) the term \"Indian tribe\" means any tribe, band, nation, pueblo, or other organized group or community of Indians, including any Alaska Native village (as defined in, or established pursuant to, the Alaska Native Claims Settlement Act (43 U.S.C. 1601 et seq.)), which is recognized as eligible for the special programs and services provided by the United States to Indians because of their status as Indians;"],[1,"(3) the term \"Indian religion\" means any religion—"],[2,"(A) which is practiced by Indians, and"],[2,"(B) the origin and interpretation of which is from within a traditional Indian culture or community; and"],[1,"(4) the term \"State\" means any State of the United States, and any political subdivision thereof."],[0,"(d) Protection of rights of Indians and Indian tribes"],[0,"Nothing in this section shall be construed as abrogating, diminishing, or otherwise affecting—"],[1,"(1) the inherent rights of any Indian tribe;"],[1,"(2) the rights, express or implicit, of any Indian tribe which exist under treaties, Executive orders, and laws of the United States;"],[1,"(3) the inherent right of Indians to practice their religions; and"],[1,"(4) the right of Indians to practice their religions under any Federal or State law."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1996a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1996a. Traditional Indian religious use of peyote","tname":"The Public Health and Welfare","by":{"0":"27, 27, 27, 27, 28, 27, 27, 27"}},{"t":"usc","label":"21 U.S.C. § 801","url":"https://www.law.cornell.edu/uscode/text/21/801","subs":["(2)","(5)"],"stext":{"head":"§801. Congressional findings and declarations: controlled substances","paras":[[0,"The Congress makes the following findings and declarations:"],[0,"(1) Many of the drugs included within this subchapter have a useful and legitimate medical purpose and are necessary to maintain the health and general welfare of the American people."],[0,"(2) The illegal importation, manufacture, distribution, and possession and improper use of controlled substances have a substantial and detrimental effect on the health and general welfare of the American people."],[0,"(3) A major portion of the traffic in controlled substances flows through interstate and foreign commerce. Incidents of the traffic which are not an integral part of the interstate or foreign flow, such as manufacture, local distribution, and possession, nonetheless have a substantial and direct effect upon interstate commerce because—"],[1,"(A) after manufacture, many controlled substances are transported in interstate commerce,"],[1,"(B) controlled substances distributed locally usually have been transported in interstate commerce immediately before their distribution, and"],[1,"(C) controlled substances possessed commonly flow through interstate commerce immediately prior to such possession."],[0,"(4) Local distribution and possession of controlled substances contribute to swelling the interstate traffic in such substances."],[0,"(5) Controlled substances manufactured and distributed intrastate cannot be differentiated from controlled substances manufactured and distributed interstate. Thus, it is not feasible to distinguish, in terms of controls, between controlled substances manufactured and distributed interstate and controlled substances manufactured and distributed intrastate."],[0,"(6) Federal control of the intrastate incidents of the traffic in controlled substances is essential to the effective control of the interstate incidents of such traffic."],[0,"(7) The United States is a party to the Single Convention on Narcotic Drugs, 1961, and other international conventions designed to establish effective control over international and domestic traffic in controlled substances."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/801?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§801. Congressional findings and declarations: controlled substances","tname":"Food and Drugs","by":{"0":"18, 21, 21"}},{"t":"usc","label":"21 U.S.C. § 801a","url":"https://www.law.cornell.edu/uscode/text/21/801a","subs":["(2)"],"by":{"0":"46"}},{"t":"usc","label":"21 U.S.C. § 811","url":"https://www.law.cornell.edu/uscode/text/21/811","by":{"0":"23"}},{"t":"usc","label":"21 U.S.C. § 812","url":"https://www.law.cornell.edu/uscode/text/21/812","subs":["(b)","(b)(1)(A)","(b)(1)(C)","(c)"],"stext":{"head":"§812. Schedules of controlled substances","paras":[[0,"(a) Establishment"],[0,"There are established five schedules of controlled substances, to be known as schedules I, II, III, IV, and V. Such schedules shall initially consist of the substances listed in this section. The schedules established by this section shall be updated and republished on a semiannual basis during the two-year period beginning one year after October 27, 1970, and shall be updated and republished on an annual basis thereafter.1"],[0,"(b) Placement on schedules; findings required"],[0,"Except where control is required by United States obligations under an international treaty, convention, or protocol, in effect on October 27, 1970, and except in the case of an immediate precursor, a drug or other substance may not be placed in any schedule unless the findings required for such schedule are made with respect to such drug or other substance. The findings required for each of the schedules are as follows:"],[0,"(1) Schedule I.—"],[1,"(A) The drug or other substance has a high potential for abuse."],[1,"(B) The drug or other substance has no currently accepted medical use in treatment in the United States."],[1,"(C) There is a lack of accepted safety for use of the drug or other substance under medical supervision."],[0,"(2) Schedule II.—"],[1,"(A) The drug or other substance has a high potential for abuse."],[1,"(B) The drug or other substance has a currently accepted medical use in treatment in the United States or a currently accepted medical use with severe restrictions."],[1,"(C) Abuse of the drug or other substances may lead to severe psychological or physical dependence."],[0,"(3) Schedule III.—"],[1,"(A) The drug or other substance has a potential for abuse less than the drugs or other substances in schedules I and II."],[1,"(B) The drug or other substance has a currently accepted medical use in treatment in the United States."],[1,"(C) Abuse of the drug or other substance may lead to moderate or low physical dependence or high psychological dependence."],[0,"(4) Schedule IV.—"],[1,"(A) The drug or other substance has a low potential for abuse relative to the drugs or other substances in schedule III."],[1,"(B) The drug or other substance has a currently accepted medical use in treatment in the United States."],[1,"(C) Abuse of the drug or other substance may lead to limited physical dependence or psychological dependence relative to the drugs or other substances in schedule III."],[0,"(5) Schedule V.—"],[1,"(A) The drug or other substance has a low potential for abuse relative to the drugs or other substances in schedule IV."],[1,"(B) The drug or other substance has a currently accepted medical use in treatment in the United States."],[1,"(C) Abuse of the drug or other substance may lead to limited physical dependence or psychological dependence relative to the drugs or other substances in schedule IV."],[0,"(c) Initial schedules of controlled substances"],[0,"Schedules I, II, III, IV, and V shall, unless and until amended pursuant to section 811 of this title, consist of the following drugs or other substances,1 by whatever official name, common or usual name, chemical name, or brand name designated:"],[0,"(a) Unless specifically excepted or unless listed in another schedule, any of the following opiates, including their isomers, esters, ethers, salts, and salts of isomers, esters, and ethers, whenever the existence of such isomers, esters, ethers, and salts is possible within the specific chemical designation:"],[1,"(1) Acetylmethadol."],[1,"(2) Allylprodine."],[1,"(3) Alphacetylmathadol.2"],[1,"(4) Alphameprodine."],[1,"(5) Alphamethadol."],[1,"(6) Benzethidine."],[1,"(7) Betacetylmethadol."],[1,"(8) Betameprodine."],[1,"(9) Betamethadol."],[1,"(10) Betaprodine."],[1,"(11) Clonitazene."],[1,"(12) Dextromoramide."],[1,"(13) Dextrorphan."],[1,"(14) Diampromide."],[1,"(15) Diethylthiambutene."],[1,"(16) Dimenoxadol."],[1,"(17) Dimepheptanol."],[1,"(18) Dimethylthiambutene."],[1,"(19) Dioxaphetyl butyrate."],[1,"(20) Dipipanone."],[1,"(21) Ethylmethylthiambutene."],[1,"(22) Etonitazene."],[1,"(23) Etoxeridine."],[1,"(24) Furethidine."],[1,"(25) Hydroxypethidine."],[1,"(26) Ketobemidone."],[1,"(27) Levomoramide."],[1,"(28) Levophenacylmorphan."],[1,"(29) Morpheridine."],[1,"(30) Noracymethadol."],[1,"(31) Norlevorphanol."],[1,"(32) Normethadone."],[1,"(33) Norpipanone."],[1,"(34) Phenadoxone."],[1,"(35) Phenampromide."],[1,"(36) Phenomorphan."],[1,"(37) Phenoperidine."],[1,"(38) Piritramide."],[1,"(39) Proheptazine."],[1,"(40) Properidine."],[1,"(41) Racemoramide."],[1,"(42) Trimeperidine."],[0,"(b) Unless specifically excepted or unless listed in another schedule, any of the following opium derivatives, their salts, isomers, and salts of isomers whenever the existence of such salts, isomers, and salts of isomers is possible within the specific chemical designation:"],[1,"(1) Acetorphine."],[1,"(2) Acetyldihydrocodeine."],[1,"(3) Benzylmorphine."],[1,"(4) Codeine methylbromide."],[1,"(5) Codeine-N-Oxide."],[1,"(6) Cyprenorphine."],[1,"(7) Desomorphine."],[1,"(8) Dihydromorphine."],[1,"(9) Etorphine."],[1,"(10) Heroin."],[1,"(11) Hydromorphinol."],[1,"(12) Methyldesorphine."],[1,"(13) Methylhydromorphine."],[1,"(14) Morphine methylbromide."],[1,"(15) Morphine methylsulfonate."],[1,"(16) Morphine-N-Oxide."],[1,"(17) Myrophine."],[1,"(18) Nicocodeine."],[1,"(19) Nicomorphine."],[1,"(20) Normorphine."],[1,"(21) Pholcodine."],[1,"(22) Thebacon."],[0,"(c) Unless specifically excepted or unless listed in another schedule, any material, compound, mixture, or preparation, which contains any quantity of the following hallucinogenic substances, or which contains any of their salts, isomers, and salts of isomers whenever the existence of such salts, isomers, and salts of isomers is possible within the specific chemical designation:"],[1,"(1) 3,4-methylenedioxy amphetamine."],[1,"(2) 5-methoxy-3,4-methylenedioxy amphetamine."],[1,"(3) 3,4,5-trimethoxy amphetamine."],[1,"(4) Bufotenine."],[1,"(5) Diethyltryptamine."],[1,"(6) Dimethyltryptamine."],[1,"(7) 4-methyl-2,5-dimethoxyamphetamine."],[1,"(8) Ibogaine."],[1,"(9) Lysergic acid diethylamide."],[1,"(10) Marihuana."],[1,"(11) Mescaline."],[1,"(12) Peyote."],[1,"(13) N-ethyl-3-piperidyl benzilate."],[1,"(14) N-methyl-3-piperidyl benzilate."],[1,"(15) Psilocybin."],[1,"(16) Psilocyn."],[1,"(17) Tetrahydrocannabinols, except for tetrahydrocannabinols in hemp (as defined under section 1639o of title 7)."],[1,"(18) 4-methylmethcathinone (Mephedrone)."],[1,"(19) 3,4-methylenedioxypyrovalerone (MDPV)."],[1,"(20) 2-(2,5-Dimethoxy-4-ethylphenyl)ethanamine (2C–E)."],[1,"(21) 2-(2,5-Dimethoxy-4-methylphenyl)ethanamine (2C–D)."],[1,"(22) 2-(4-Chloro-2,5-dimethoxyphenyl)ethanamine (2C–C)."],[1,"(23) 2-(4-Iodo-2,5-dimethoxyphenyl)ethanamine (2C–I)."],[1,"(24) 2-[4-(Ethylthio)-2,5-dimethoxyphenyl]ethanamine (2C–T–2)."],[1,"(25) 2-[4-(Isopropylthio)-2,5-dimethoxyphenyl]ethanamine (2C–T–4)."],[1,"(26) 2-(2,5-Dimethoxyphenyl)ethanamine (2C–H)."],[1,"(27) 2-(2,5-Dimethoxy-4-nitro-phenyl)ethanamine (2C–N)."],[1,"(28) 2-(2,5-Dimethoxy-4-(n)-propylphenyl)ethanamine (2C–P)."],[0,"(d)(1) Unless specifically exempted or unless listed in another schedule, any material, compound, mixture, or preparation which contains any quantity of cannabimimetic agents, or which contains their salts, isomers, and salts of isomers whenever the existence of such salts, isomers, and salts of isomers is possible within the specific chemical designation."],[0,"(2) In paragraph (1):"],[1,"(A) The term \"cannabimimetic agents\" means any substance that is a cannabinoid receptor type 1 (CB1 receptor) agonist as demonstrated by binding studies and functional assays within any of the following structural classes:"],[2,"(i) 2-(3-hydroxycyclohexyl)phenol with substitution at the 5-position of the phenolic ring by alkyl or alkenyl, whether or not substituted on the cyclohexyl ring to any extent."],[2,"(ii) 3-(1-naphthoyl)indole or 3-(1-naphthylmethane)indole by substitution at the nitrogen atom of the indole ring, whether or not further substituted on the indole ring to any extent, whether or not substituted on the naphthoyl or naphthyl ring to any extent."],[2,"(iii) 3-(1-naphthoyl)pyrrole by substitution at the nitrogen atom of the pyrrole ring, whether or not further substituted in the pyrrole ring to any extent, whether or not substituted on the naphthoyl ring to any extent."],[2,"(iv) 1-(1-naphthylmethylene)indene by substitution of the 3-position of the indene ring, whether or not further substituted in the indene ring to any extent, whether or not substituted on the naphthyl ring to any extent."],[2,"(v) 3-phenylacetylindole or 3-benzoylindole by substitution at the nitrogen atom of the indole ring, whether or not further substituted in the indole ring to any extent, whether or not substituted on the phenyl ring to any extent."],[1,"(B) Such term includes—"],[2,"(i) 5-(1,1-dimethylheptyl)-2-[(1R,3S)-3-hydroxycyclohexyl]-phenol (CP–47,497);"],[2,"(ii) 5-(1,1-dimethyloctyl)-2-[(1R,3S)-3-hydroxycyclohexyl]-phenol (cannabicyclohexanol or CP–47,497 C8-homolog);"],[2,"(iii) 1-pentyl-3-(1-naphthoyl)indole (JWH–018 and AM678);"],[2,"(iv) 1-butyl-3-(1-naphthoyl)indole (JWH–073);"],[2,"(v) 1-hexyl-3-(1-naphthoyl)indole (JWH–019);"],[2,"(vi) 1-[2-(4-morpholinyl)ethyl]-3-(1-naphthoyl)indole (JWH–200);"],[2,"(vii) 1-pentyl-3-(2-methoxyphenylacetyl)indole (JWH–250);"],[2,"(viii) 1-pentyl-3-[1-(4-methoxynaphthoyl)]indole (JWH–081);"],[2,"(ix) 1-pentyl-3-(4-methyl-1-naphthoyl)indole (JWH–122);"],[2,"(x) 1-pentyl-3-(4-chloro-1-naphthoyl)indole (JWH–398);"],[2,"(xi) 1-(5-fluoropentyl)-3-(1-naphthoyl)indole (AM2201);"],[2,"(xii) 1-(5-fluoropentyl)-3-(2-iodobenzoyl)indole (AM694);"],[2,"(xiii) 1-pentyl-3-[(4-methoxy)-benzoyl]indole (SR–19 and RCS–4);"],[2,"(xiv) 1-cyclohexylethyl-3-(2-methoxyphenylacetyl)indole (SR–18 and RCS–8); and"],[2,"(xv) 1-pentyl-3-(2-chlorophenylacetyl)indole (JWH–203)."],[0,"(a) Unless specifically excepted or unless listed in another schedule, any of the following substances whether produced directly or indirectly by extraction from substances of vegetable origin, or independently by means of chemical synthesis, or by a combination of extraction and chemical synthesis:"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/812?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§812. Schedules of controlled substances","tname":"Food and Drugs","by":{"0":"21, 17, 31, 32, 38, 31, 32, 3, 16, 35"}},{"t":"usc","label":"21 U.S.C. § 823","url":"https://www.law.cornell.edu/uscode/text/21/823","stext":{"head":"§823. Registration requirements","paras":[[0,"(a) Manufacturers of controlled substances in schedule I or II"],[0,"The Attorney General shall register an applicant to manufacture controlled substances in schedule I or II if he determines that such registration is consistent with the public interest and with United States obligations under international treaties, conventions, or protocols in effect on May 1, 1971. In determining the public interest, the following factors shall be considered:"],[1,"(1) maintenance of effective controls against diversion of particular controlled substances and any controlled substance in schedule I or II compounded therefrom into other than legitimate medical, scientific, research, or industrial channels, by limiting the importation and bulk manufacture of such controlled substances to a number of establishments which can produce an adequate and uninterrupted supply of these substances under adequately competitive conditions for legitimate medical, scientific, research, and industrial purposes;"],[1,"(2) compliance with applicable State and local law;"],[1,"(3) promotion of technical advances in the art of manufacturing these substances and the development of new substances;"],[1,"(4) prior conviction record of applicant under Federal and State laws relating to the manufacture, distribution, or dispensing of such substances;"],[1,"(5) past experience in the manufacture of controlled substances, and the existence in the establishment of effective control against diversion; and"],[1,"(6) such other factors as may be relevant to and consistent with the public health and safety."],[0,"(b) Distributors of controlled substances in schedule I or II"],[0,"The Attorney General shall register an applicant to distribute a controlled substance in schedule I or II unless he determines that the issuance of such registration is inconsistent with the public interest. In determining the public interest, the following factors shall be considered:"],[1,"(1) maintenance of effective control against diversion of particular controlled substances into other than legitimate medical, scientific, and industrial channels;"],[1,"(2) compliance with applicable State and local law;"],[1,"(3) prior conviction record of applicant under Federal or State laws relating to the manufacture, distribution, or dispensing of such substances;"],[1,"(4) past experience in the distribution of controlled substances; and"],[1,"(5) such other factors as may be relevant to and consistent with the public health and safety."],[0,"(c) Manufacturers of marijuana for research purposes"],[0,"(1)(A) As it relates to applications to manufacture marijuana for research purposes, when the Attorney General places a notice in the Federal Register to increase the number of entities registered under this chapter to manufacture marijuana to supply appropriately registered researchers in the United States, the Attorney General shall, not later than 60 days after the date on which the Attorney General receives a completed application—"],[1,"(i) approve the application; or"],[1,"(ii) request supplemental information."],[0,"(B) For purposes of subparagraph (A), an application shall be deemed complete when the applicant has submitted documentation showing each of the following:"],[1,"(i) The requirements designated in the notice in the Federal Register are satisfied."],[1,"(ii) The requirements under this chapter are satisfied."],[1,"(iii) The applicant will limit the transfer and sale of any marijuana manufactured under this subsection—"],[2,"(I) to researchers who are registered under this chapter to conduct research with controlled substances in schedule I; and"],[2,"(II) for purposes of use in preclinical research or in a clinical investigation pursuant to an investigational new drug exemption under 355(i) 1 of this title."],[1,"(iv) The applicant will transfer or sell any marijuana manufactured under this subsection only with prior, written consent for the transfer or sale by the Attorney General."],[1,"(v) The applicant has completed the application and review process under subsection (a) for the bulk manufacture of controlled substances in schedule I."],[1,"(vi) The applicant has established and begun operation of a process for storage and handling of controlled substances in schedule I, including for inventory control and monitoring security in accordance with section 105 of the Medical Marijuana and Cannabidiol Research Expansion Act."],[1,"(vii) The applicant is licensed by each State in which the applicant will conduct operations under this subsection, to manufacture marijuana, if that State requires such a license."],[0,"(C) Not later than 30 days after the date on which the Attorney General receives supplemental information requested under subparagraph (A)(ii) with respect to an application, the Attorney General shall approve or deny the application."],[0,"(2) If an application described in this subsection is denied, the Attorney General shall provide a written explanation of the basis of denial to the applicant."],[0,"(d) Limits of authorized activities"],[0,"Registration granted under subsections (a) and (b) of this section shall not entitle a registrant to (1) manufacture or distribute controlled substances in schedule I or II other than those specified in the registration, or (2) manufacture any quantity of those controlled substances in excess of the quota assigned pursuant to section 826 of this title."],[0,"(e) Manufacturers of controlled substances in schedule III, IV, or V"],[0,"The Attorney General shall register an applicant to manufacture controlled substances in schedule III, IV, or V, unless he determines that the issuance of such registration is inconsistent with the public interest. In determining the public interest, the following factors shall be considered:"],[1,"(1) maintenance of effective controls against diversion of particular controlled substances and any controlled substance in schedule III, IV, or V compounded therefrom into other than legitimate medical, scientific, or industrial channels;"],[1,"(2) compliance with applicable State and local law;"],[1,"(3) promotion of technical advances in the art of manufacturing these substances and the development of new substances;"],[1,"(4) prior conviction record of applicant under Federal or State laws relating to the manufacture, distribution, or dispensing of such substances;"],[1,"(5) past experience in the manufacture, distribution, and dispensing of controlled substances, and the existence in the establishment of effective controls against diversion; and"],[1,"(6) such other factors as may be relevant to and consistent with the public health and safety."],[0,"(f) Distributors of controlled substances in schedule III, IV, or V"],[0,"The Attorney General shall register an applicant to distribute controlled substances in schedule III, IV, or V, unless he determines that the issuance of such registration is inconsistent with the public interest. In determining the public interest, the following factors shall be considered:"],[1,"(1) maintenance of effective controls against diversion of particular controlled substances into other than legitimate medical, scientific, and industrial channels;"],[1,"(2) compliance with applicable State and local law;"],[1,"(3) prior conviction record of applicant under Federal or State laws relating to the manufacture, distribution, or dispensing of such substances;"],[1,"(4) past experience in the distribution of controlled substances; and"],[1,"(5) such other factors as may be relevant to and consistent with the public health and safety."],[0,"(g) Research by practitioners; pharmacies; research applications; construction of Article 7 of the Convention on Psychotropic Substances"],[0,"(1) The Attorney General shall register practitioners (including pharmacies, as distinguished from pharmacists) to dispense, or conduct research with, controlled substances in schedule II, III, IV, or V and shall modify the registrations of pharmacies so registered to authorize them to dispense controlled substances by means of the Internet, if the applicant is authorized to dispense, or conduct research with respect to, controlled substances under the laws of the State in which he practices. The Attorney General may deny an application for such registration or such modification of registration if the Attorney General determines that the issuance of such registration or modification would be inconsistent with the public interest. In determining the public interest, the following factors shall be considered:"],[1,"(A) The recommendation of the appropriate State licensing board or professional disciplinary authority."],[1,"(B) The applicant's experience in dispensing, or conducting research with respect to controlled substances."],[1,"(C) The applicant's conviction record under Federal or State laws relating to the manufacture, distribution, or dispensing of controlled substances."],[1,"(D) Compliance with applicable State, Federal, or local laws relating to controlled substances."],[1,"(E) Such other conduct which may threaten the public health and safety."],[0,"Separate registration under this part for practitioners engaging in research with controlled substances in schedule II, III, IV, or V, who are already registered under this part in another capacity, shall not be required."],[0,"(2)(A) Registration applications by practitioners wishing to conduct research with controlled substances in schedule I shall be referred to the Secretary, who shall determine the qualifications and competency of each practitioner requesting registration, as well as the merits of the research protocol. The Secretary, in determining the merits of each research protocol, shall consult with the Attorney General as to effective procedures to adequately safeguard against diversion of such controlled substances from legitimate medical or scientific use. Registration for the purpose of bona fide research with controlled substances in schedule I by a practitioner deemed qualified by the Secretary may be denied by the Attorney General only on a ground specified in section 824(a) of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/823?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§823. Registration requirements","tname":"Food and Drugs","by":{"0":"21"}},{"t":"usc","label":"21 U.S.C. § 844","url":"https://www.law.cornell.edu/uscode/text/21/844","subs":["(a)"],"by":{"0":"21"}},{"t":"law","label":"Pub. L. No. 95-633","url":"https://www.govinfo.gov/link/statute/92/3768","by":{"0":"45"}},{"t":"usc","label":"42 U.S.C. § 2000bb","url":"https://www.law.cornell.edu/uscode/text/42/2000bb","subs":["(a)(5)","(b)(1)"],"stext":{"head":"§2000bb. Congressional findings and declaration of purposes","paras":[[0,"(a) Findings"],[0,"The Congress finds that—"],[1,"(1) the framers of the Constitution, recognizing free exercise of religion as an unalienable right, secured its protection in the First Amendment to the Constitution;"],[1,"(2) laws \"neutral\" toward religion may burden religious exercise as surely as laws intended to interfere with religious exercise;"],[1,"(3) governments should not substantially burden religious exercise without compelling justification;"],[1,"(4) in Employment Division v. Smith, 494 U.S. 872 (1990) the Supreme Court virtually eliminated the requirement that the government justify burdens on religious exercise imposed by laws neutral toward religion; and"],[1,"(5) the compelling interest test as set forth in prior Federal court rulings is a workable test for striking sensible balances between religious liberty and competing prior governmental interests."],[0,"(b) Purposes"],[0,"The purposes of this chapter are—"],[1,"(1) to restore the compelling interest test as set forth in Sherbert v. Verner, 374 U.S. 398 (1963) and Wisconsin v. Yoder, 406 U.S. 205 (1972) and to guarantee its application in all cases where free exercise of religion is substantially burdened; and"],[1,"(2) to provide a claim or defense to persons whose religious exercise is substantially burdened by government."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000bb?type=usc&year=mostrecent&link-type=html"},"op":11,"head":"§2000bb. Congressional findings and declaration of purposes","tname":"The Public Health and Welfare","by":{"0":"4, 9, 10, 26, 47, 26"}},{"t":"usc","label":"42 U.S.C. § 2000bb-1","url":"https://www.law.cornell.edu/uscode/text/42/2000bb-1","subs":["(a)"],"by":{"0":"42"}},{"t":"usc","label":"42 U.S.C. § 2000bb-2","url":"https://www.law.cornell.edu/uscode/text/42/2000bb-2","subs":["(3)"],"by":{"0":"12"}},{"t":"usc","label":"42 U.S.C. § 2000bb-3","url":"https://www.law.cornell.edu/uscode/text/42/2000bb-3","subs":["(a)"],"by":{"0":"4, 41"}},{"t":"usc","label":"42 U.S.C. § 2000cc","url":"https://www.law.cornell.edu/uscode/text/42/2000cc","by":{"0":"10"}},{"t":"usc","label":"25 U.S.C. § 2901","url":"https://www.law.cornell.edu/uscode/text/25/2901","subs":["(1)"],"by":{"0":"25"}},{"t":"reg","label":"Church of the Living Tree: Denial of Application, 68 Fed. Reg. 17,403","url":"https://www.govinfo.gov/link/fr/68/17403","by":{"0":"22"}},{"t":"reg","label":"31 Fed. Reg. 4679","url":"https://www.govinfo.gov/link/fr/31/4679","by":{"0":"16"}},{"t":"reg","label":"Genesis 1:29 Corporation: Denial of Application, 68 Fed. Reg. 15,225","url":"https://www.govinfo.gov/link/fr/68/15225","by":{"0":"22"}}]};